"""Deterministic payloads for authoritative metadata files."""

import base64
import zlib

AUTHORITATIVE_METADATA_PAYLOADS = {
    'assets/blindboxchallenge/lang/zh_cn.json': '',
    'assets/blindboxchallenge/lang/en_us.json': '',
    'META-INF/mods.toml': '',
    'pack.mcmeta': 'eNqr5uVSUFAqSEzOVrJSqAZxoNz4tPyi3MQSoKihqQ5UPCW1OLkos6AkMz8PKK70fPam57MnPeuZ+KxjxvMp85+unfFia8uzXROUQMpreblqebkAjToiWw==',
}


def decode_authoritative_metadata(relative: str) -> bytes:
    return zlib.decompress(base64.b64decode(AUTHORITATIVE_METADATA_PAYLOADS[relative], validate=True))
